<?php
namespace App\Http\Controllers;
use App\Models\Student;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\StreamedResponse;
class ExportController extends Controller {
 public function students(Request $r):StreamedResponse {abort_unless($r->user()->isAdmin(),403);$rows=Student::with('section')->when($r->status&&$r->status!=='all',fn($q)=>$q->where('status',$r->status))->when($r->section_id,fn($q,$id)=>$q->where('section_id',$id))->orderBy('last_name')->get();return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['Student Number','First Name','Middle Name','Last Name','Email','Section','Status']);foreach($rows as $s)fputcsv($out,[$s->student_number,$s->first_name,$s->middle_name,$s->last_name,$s->email,$s->section?->section_name,$s->status]);fclose($out);},'gradeflow-students-'.now()->format('Ymd').'.csv',['Content-Type'=>'text/csv']);}
 public function grades(Request $r,GradeRecordController $controller):StreamedResponse {$rows=$controller->filtered($r)->get();return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['Student Number','Student','Subject','Section','Prelim','Midterm','Final','Final Grade','Remarks','Status']);foreach($rows as $g){$e=$g->enrollment;$a=$e->classAssignment;fputcsv($out,[$e->student->student_number,$e->student->full_name,$a->subject->subject_code,$a->section->section_name,$g->prelim,$g->midterm,$g->final,$g->final_grade,$g->remarks,$g->status]);}fclose($out);},'gradeflow-grades-'.now()->format('Ymd').'.csv',['Content-Type'=>'text/csv']);}
}
